CREATE TABLE CAFICULTOR (caficultor_id uuid DEFAULT uuidv7(), tipo_caficultor_id int2 NOT NULL, fecha_registro timestamp NOT NULL, cacerio varchar(50), PRIMARY KEY (caficultor_id));
CREATE TABLE CATEGORIA (id SERIAL NOT NULL, nombre varchar(10) NOT NULL, cantidad_defectos int4 NOT NULL, PRIMARY KEY (id));
CREATE TABLE COOPERATIVA (id uuid DEFAULT uuidv7(), nombre varchar(100) NOT NULL, codigo varchar(20) NOT NULL, direccion varchar(255) NOT NULL UNIQUE, telefono char(9) NOT NULL, correo varchar(255) NOT NULL, descripcion varchar(255) NOT NULL, imagen_url varchar(255), estado char(1) NOT NULL, fecha_registro timestamp NOT NULL, ubigeo_id char(6) NOT NULL, PRIMARY KEY (id));
CREATE TABLE DETALLE_EVALUACION (id uuid DEFAULT uuidv7(), cantidad int4 NOT NULL, evaluacion_id uuid DEFAULT uuidv7(), tipo_defecto_id int2 NOT NULL, PRIMARY KEY (id));
CREATE TABLE EVALUACION (id uuid DEFAULT uuidv7(), codigo char(10), personal_id uuid DEFAULT uuidv7(), caficultor_id uuid DEFAULT uuidv7(), tipo_caficultor_id int2 NOT NULL, valor_cafe_id uuid, num_sacos int2 NOT NULL, peso_bruto numeric(7, 2) NOT NULL, humedad int2 NOT NULL, peso_muestra numeric(7, 2) NOT NULL, peso_trillado numeric(7, 2) NOT NULL, peso_cascara numeric(7, 2), peso_cascara_total numeric(7, 2), num_tamiz int2 NOT NULL, peso_tamizado numeric(7, 2) NOT NULL, peso_bueno numeric(7, 2), peso_malo numeric(7, 2), factor_rendimiento numeric(7, 2), tara_saco numeric(3, 2), tara_total int2, peso_neto int4, peso_por_qq numeric(7, 2), pago numeric(7, 2), fecha timestamp, tipo_grano_id int4 NOT NULL, categoria_id int4, total_defectos int4, PRIMARY KEY (id));
CREATE TABLE PERSONA (id uuid DEFAULT uuidv7(), nombre varchar(50) NOT NULL, ape_paterno varchar(30) NOT NULL, ape_materno varchar(30) NOT NULL, sexo char(1) NOT NULL, fecha_nacimiento date NOT NULL, tipo_documento_id int2 NOT NULL, num_documento varchar(12) NOT NULL UNIQUE, telefono char(9), ubigeo char(6), estado char(1) NOT NULL, cooperativa_id uuid DEFAULT uuidv7(), correo varchar(100), PRIMARY KEY (id));
CREATE TABLE PERSONAL (personal_id uuid DEFAULT uuidv7(), tipo_personal_id int2 NOT NULL, usuario varchar(30) NOT NULL UNIQUE, clave varchar(255) NOT NULL, estado char(1) NOT NULL, fecha_registro timestamp NOT NULL, PRIMARY KEY (personal_id));
CREATE TABLE TIPO_CAFICULTOR (id SERIAL NOT NULL, nombre varchar(50) NOT NULL, PRIMARY KEY (id));
CREATE TABLE TIPO_DEFECTO (id SERIAL NOT NULL, nombre varchar(50) NOT NULL, descripcion text, PRIMARY KEY (id));
CREATE TABLE TIPO_DOCUMENTO (id SERIAL NOT NULL, nombre varchar(50) NOT NULL, PRIMARY KEY (id));
CREATE TABLE TIPO_GRANO (id SERIAL NOT NULL, nombre varchar(20) NOT NULL UNIQUE, peso_qq numeric(5, 2) NOT NULL, PRIMARY KEY (id));
CREATE TABLE TIPO_PERSONAL (id SERIAL NOT NULL, nombre varchar(50) NOT NULL, PRIMARY KEY (id));
CREATE TABLE UBIGEO (ubigeo char(6) NOT NULL, departamento varchar(50) NOT NULL, provincia varchar(50) NOT NULL, distrito varchar(50) NOT NULL, PRIMARY KEY (ubigeo));
CREATE TABLE VALOR_CAFE (id uuid DEFAULT uuidv7(), rango varchar(20) NOT NULL, precio float4 NOT NULL, fecha timestamp NOT NULL, PRIMARY KEY (id));
